import{_ as e,a,o as d,a6 as o}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Catalog Products — Mass Delete","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-catalog-product-mass-delete","title":"Mass Delete Catalog Products","description":"Deletes a batch of products in one call. Ids that do not exist are skipped without an error, and `deleted` lists only the ones actually removed.","query":"mutation MassDeleteProducts($input: createAdminCatalogProductMassDeleteInput!) {\\n  createAdminCatalogProductMassDelete(input: $input) {\\n    adminCatalogProductMassDelete {\\n      _id\\n      deleted\\n      message\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": { \\"indices\\": [12, 18] }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createAdminCatalogProductMassDelete\\": {\\n      \\"adminCatalogProductMassDelete\\": {\\n        \\"_id\\": 1,\\n        \\"deleted\\": [12, 18],\\n        \\"message\\": \\"Products deleted successfully.\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/catalog/products/mass-delete.md","filePath":"api/graphql-api/admin/catalog/products/mass-delete.md","lastUpdated":1787725411000}'),r={name:"api/graphql-api/admin/catalog/products/mass-delete.md"};function s(i,t,n,l,c,h){return d(),a("div",null,t[0]||(t[0]=[o('<h1 id="catalog-products-—-mass-delete" tabindex="-1">Catalog Products — Mass Delete <a class="header-anchor" href="#catalog-products-—-mass-delete" aria-label="Permalink to &quot;Catalog Products — Mass Delete&quot;">​</a></h1><p>Equivalent to <a href="/api/rest-api/admin/catalog/products/mass-delete.html"><code>POST /api/admin/catalog/products/mass-delete</code></a>.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th></tr></thead><tbody><tr><td><code>createAdminCatalogProductMassDelete</code></td><td>Mutation</td></tr></tbody></table><h2 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;Input&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>indices</code></td><td>Iterable</td><td>Yes</td><td>Non-empty list of product ids.</td></tr></tbody></table><h2 id="payload-fields" tabindex="-1">Payload Fields <a class="header-anchor" href="#payload-fields" aria-label="Permalink to &quot;Payload Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>_id</code></td><td>Int</td><td>Always <code>1</code>. This is an action result, not a record — ignore it.</td></tr><tr><td><code>deleted</code></td><td>Iterable</td><td>The ids that were actually removed.</td></tr><tr><td><code>message</code></td><td>String</td><td>Translated confirmation.</td></tr></tbody></table><p><strong><code>deleted</code> is not an echo of <code>indices</code>.</strong> Ids that do not exist are dropped silently, so sending <code>[1403, 999999]</code> returns <code>deleted: [1403]</code>. Compare the two lists to find out what was skipped — nothing else reports it.</p><p>Select <code>_id</code>, not <code>id</code>. This is a routeless action result, so its <code>id</code> is not a queryable path.</p><h2 id="behaviour" tabindex="-1">Behaviour <a class="header-anchor" href="#behaviour" aria-label="Permalink to &quot;Behaviour&quot;">​</a></h2><ul><li><strong>Best effort, no transaction.</strong> The batch does not roll back if one id fails partway through; ids processed before the failure stay deleted.</li><li><strong>Configurable variants cascade</strong> with their parent, so a parent id can remove more rows than you listed.</li><li><strong>Order history is unaffected</strong> — order items keep their product snapshot.</li></ul><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Cause</th></tr></thead><tbody><tr><td><code>The indices field is required and must be a non-empty array.</code></td><td>Missing or empty <code>indices</code></td></tr><tr><td><code>You do not have permission to manage products.</code></td><td>Token lacks <code>catalog.products.delete</code></td></tr></tbody></table>',14)]))}const m=e(r,[["render",s]]);export{u as __pageData,m as default};
